from datetime import datetime, timezone

DEFAULTS = (5, 8.0, 120.0)  # attempts, backoff cap, longest Retry-After

# service (lowercase) -> (attempts, backoff cap, longest accepted Retry-After)
PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

RETRYABLE_STATUSES = {429, 502, 503, 504}
IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
MONTHS = {m: i for i, m in enumerate(
    "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split(), 1)}
HTTP_DATE = re.compile(
    r"(Mon|Tue|Wed|Thu|Fri|Sat|Sun), ([0-9]{2}) ([A-Z][a-z]{2}) ([0-9]{4}) "
    r"([0-9]{2}):([0-9]{2}):([0-9]{2}) GMT"
)


def _header(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    """Wait in seconds from a Retry-After value, or None if absent/malformed."""
    if not isinstance(value, str):
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    m = HTTP_DATE.fullmatch(value)
    if not m or m.group(3) not in MONTHS:
        return None
    try:
        when = datetime(
            int(m.group(4)), MONTHS[m.group(3)], int(m.group(2)),
            int(m.group(5)), int(m.group(6)), int(m.group(7)),
            tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())
''')
s=s.replace("    raise NotImplementedError\n",'''    if status is not None and status not in RETRYABLE_STATUSES:
        return None
    method = method.upper()
    if method not in IDEMPOTENT_METHODS:
        key = _header(request_headers, "idempotency-key")
        if method not in ("POST", "PATCH") or not (key and key.strip()):
            return None

    service = _header(request_headers, "x-service")
    limit, cap, longest = PROFILES.get(
        service.strip().lower() if isinstance(service, str) else "", DEFAULTS
    )
    if attempt >= limit:
        return None

    delay = min(cap, 0.25 * 2 ** (attempt - 1))
    if status in (429, 503):
        wait = _retry_after(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > longest:
                return None
            delay = max(delay, wait)
    return delay
''')
